<?php
declare(strict_types=1);
namespace App\Application\Review\Service;
use App\Application\Review\DTO\Response\MasteryMapNodeResponseDto;use App\Application\Review\DTO\Response\MasteryMapResponseDto;use App\Domain\Review\Repository\UserConceptMasteryRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final readonly class GetMasteryMapService { public function __construct(private UserConceptMasteryRepositoryInterface $mastery,private TaxonomySubjectRepositoryInterface $subjects){} public function execute(string $userId,int $page=1,int $perPage=25):MasteryMapResponseDto{if($page<1||$perPage<1||$perPage>100)throw new \InvalidArgumentException('Paginação inválida.');$items=[];foreach($this->mastery->listForUser($userId,($page-1)*$perPage,$perPage) as $value){$subject=$this->subjects->findById($value->taxonomySubjectId);if($subject===null)continue;$items[]=new MasteryMapNodeResponseDto($subject->id,$subject->parentId,$subject->name,$value->masteryScore,$value->confidence->value,$value->evidenceCount,$value->lastEvidenceAt?->format(DATE_ATOM));}return new MasteryMapResponseDto($items,$page,$perPage,$this->mastery->countForUser($userId));} }
